import re

def validate_password(password):
    problems = []
    if len(password) < 8:
        problems.append('must be at least 8 characters')
    if not re.search(r'[A-Z]', password):
        problems.append('must contain an uppercase letter')
    if not re.search(r'[a-z]', password):
        problems.append('must contain a lowercase letter')
    if not re.search(r'\d', password):
        problems.append('must contain a digit')
    if not re.search(r'[!@#$%^&*(),.?":{}|<>]', password):
        problems.append('must contain a special character')
    return problems

print(validate_password('short'))

import re

def parse_log_line(line):
    m = re.match(r'^(\S+) \[(DEBUG|INFO|WARNING|ERROR|CRITICAL)\] (.*)$', line)
    if not m:
        raise ValueError(f'malformed log line: {line!r}')
    ts, level, message = m.groups()
    return {'timestamp': ts, 'level': level, 'message': message}

