from urllib.parse import unquote_plus

def parse_query_string(query):
    params = {}
    for pair in query.lstrip('?').split('&'):
        if not pair:
            continue
        key, _, value = pair.partition('=')
        params.setdefault(unquote_plus(key), []).append(unquote_plus(value))
    return params

