import re

def parse_duration(text):
    pattern = re.compile(r'(\d+)\s*h|(\d+)\s*m|(\d+)\s*s', re.IGNORECASE)
    found = {'h': 0, 'm': 0, 's': 0}
    consumed = 0
    for m in pattern.finditer(text):
        consumed += len(m.group(0))
        unit = next(k for k, g in zip('hms', m.groups()) if g is not None)
        found[unit] += int(next(g for g in m.groups() if g is not None))
    if consumed != len(text.replace(' ', '')):
        raise ValueError(f'unparsable duration: {text!r}')
    return found['h'] * 3600 + found['m'] * 60 + found['s']

print(parse_duration('30m 1h 15s'))

def is_valid_isbn(value):
    cleaned = value.replace('-', '').replace(' ', '')
    if len(cleaned) == 10 and cleaned[:9].isdigit() and (cleaned[9].isdigit() or cleaned[9] in 'Xx'):
        total = sum((10 - i) * (10 if c in 'Xx' else int(c)) for i, c in enumerate(cleaned))
        return total % 11 == 0
    if len(cleaned) == 13 and cleaned.isdigit():
        total = sum(int(c) * (1 if i % 2 == 0 else 3) for i, c in enumerate(cleaned))
        return total % 10 == 0
    return False

