def is_valid_uuid(value):
    pattern = r'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    if value.lower().startswith('urn:uuid:'):
        value = value[9:]
    return bool(re.fullmatch(pattern, value))

