def unbalanced_parentheses(text):
    stack, bad = [], []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for i, ch in enumerate(text):
        if ch in opening:
            stack.append((ch, i))
        elif ch in pairs:
            if not stack or stack[-1][0] != pairs[ch]:
                bad.append(i)
            else:
                stack.pop()
    bad.extend(index for _, index in stack)
    return sorted(bad)

