import re

def normalize_hex_color(value):
    m = re.fullmatch(r'#([0-9a-fA-F]{3}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})', value)
    if not m:
        raise ValueError(f'not a hex color: {value!r}')
    digits = m.group(1)
    if len(digits) in (3, 4):
        digits = ''.join(ch * 2 for ch in digits[:3])
    else:
        digits = digits[:6]
    return '#' + digits.upper()

