def is_valid_card(number):
    digits = [int(c) for c in number if c.isdigit()]
    if len(digits) < 13 or len(digits) > 19:
        return False
    checksum = 0
    for i, d in enumerate(reversed(digits)):
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        checksum += d
    return checksum % 10 == 0

print(is_valid_card('4111 1111 1111 1111'), is_valid_card('4111-1111-1111-1112'))

import re

def render_template(template, context):
    def replacer(match):
        name = match.group(1).strip()
        if name not in context:
            raise KeyError(f'missing template variable: {name}')
        return str(context[name])
    return re.sub(r'\{\{(.+?)\}\}', replacer, template)

print(render_template('Hello {{ user }}, you have {{ n }} messages', {'user': 'ann', 'n': 3}))
